#include <Arduino.h>
#include <TFT_eSPI.h> // Seeed_GFX keeps the TFT_eSPI header name
#include "photo.h"    // generated by tools/convert.py

EPaper epaper;

void setup() {
  epaper.begin();
  epaper.fillScreen(TFT_WHITE);
  epaper.drawBitmap(0, 0, photo, PHOTO_WIDTH, PHOTO_HEIGHT, TFT_BLACK); // set bits = black
  epaper.update(); // e-paper only refreshes on update()
}

void loop() {}
